from ute_common_converter.to_number import to_int
from ute_common_validator.validator import IsString, IsOneOf

from ...config import ENBConfig

from .base_cl_tool import BaseClToolInterface


class UnitOperationInterface(BaseClToolInterface):
    """Keywords related to the unit operation like block/unblock."""

    def block_unit(self, type=None, number=None, serial=None, timeout='15min', **kwargs):
        """Block Unit.

        :param string type: Unit type e.g. FRHB
        :param integer number: Unit number e.g. 1. Accepts string(e.g. 1.0.1.1) for chaining configuration
        :param string serial: If set, will block FBBA unit with provided serial number (for WCDMA only)

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: serial parameter only works for a specific knife version of BTSSM CLI. Released BTSSM CLI does not support this feature yet.
                If type and number are both specified, serial param may not be used and vice versa.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        number = str(number).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        params.update({'type': type, 'number': number}) if type and number else params.update({'sn': serial})
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='blockunit', params=params, trs_ip=ne, flags=flags)

    def unblock_unit(self, type=None, number=None, serial=None, timeout='15min', **kwargs):
        """Unblock Unit.

        :param string type: Unit type e.g. FRHB
        :param integer number: Unit number e.g. 1. Accepts string(e.g. 1.0.1.1) for chaining configuration
        :param string serial: If set, will unblock FBBA unit with provided serial number (for WCDMA only)

        :return: Path(s) of collected file(s).
        :rtype: list

        :note: serial parameter only works for a specific knife version of BTSSM CLI. Released BTSSM CLI does not support this feature yet.
                If type and number are both specified, serial param may not be used and vice versa.
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        number = str(number).strip()
        params = {'ne': ne, 'pw': pw, 'timeout': timeout}
        params.update({'type': type, 'number': number}) if type and number else params.update({'sn': serial})
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='unblockunit', params=params, trs_ip=ne, flags=flags)

    def reset_unit(self, type, number, priority='normal', timeout='15min', **kwargs):
        """
        Resets unit using given type and number particularly or in chain

        :param string type:                         Unit type e.g. FRHB
        :param string number:                       Unit number e.g. 1. Accepts format(e.g. 1.0.1.1) for chaining configuration
        :param string priority:                     Priority for the operation. Supported values are: low, normal, high

        :return: Path(s) of collected file(s).
        :rtype: list
        """
        alias = kwargs.get('alias')
        alias = alias.strip() if alias else None
        timeout = self._convert_to_secs(timeout)
        config = self.command_store.get(alias).get_config()
        ne = kwargs.get('ne', config.trs_ip).strip()
        pw = kwargs.get('pw', config.pw).strip()
        number = number.strip()
        priority = priority.strip()
        self._check_priority_value(priority)
        params = {'ne': ne, 'pw': pw, 'type': type, 'number': number, 'priority': priority, 'timeout': timeout}
        nolog = config.nolog if kwargs.get('nolog') is None else kwargs.get('nolog')
        flags = ['nolog'] if nolog else []
        return self._execute_cl_tool_operation(alias=alias, timeout=timeout, operation='resetunit', params=params, trs_ip=ne, flags=flags)

    def _check_priority_value(self, priority):
        IsString().check(priority)
        IsOneOf('low', 'normal', 'high').check(priority)
